import Image from 'next/image';
import { Button } from '@/components/ui/button';
import Link from 'next/link';

export default function Hero() {
  return (
    <section className="relative w-full h-[70vh] min-h-[500px] flex items-center justify-center text-center text-white">
      <Image
        src="/epir-ring.png"
        alt="Pierścionek EPIR"
        width={120}
        height={120}
        className="mx-auto mb-6 drop-shadow-lg"
        priority
      />
      <Image
        src="https://picsum.photos/1920/1080"
        alt="Artystyczna biżuteria złota"
        fill
        className="object-cover -z-10 brightness-50"
        data-ai-hint="jewelry background"
        priority
      />
      <div className="container px-4 md:px-6">
        <div className="max-w-3xl mx-auto space-y-6">
          <h1 className="font-headline text-4xl font-bold tracking-tight sm:text-5xl md:text-6xl lg:text-7xl">
            Twoja historia, nasza pasja. Biżuteria z duszą.
          </h1>
          <p className="text-lg md:text-xl text-gray-200">
            Odkryj unikatowe dzieła sztuki jubilerskiej tworzone z miłością we Wrocławiu. Wyraź siebie z EPIR Art Jewellery.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Button asChild size="lg" className="bg-accent text-accent-foreground hover:bg-accent/90">
              <a href="https://www.epir-art.com/konsultacja" target="_blank" rel="noopener noreferrer">
                Zamów Konsultację
              </a>
            </Button>
            <Button asChild size="lg" variant="outline" className="border-white text-white hover:bg-white/10">
              <Link href="#produkty">
                Zobacz kolekcję
              </Link>
            </Button>
          </div>
        </div>
      </div>
    </section>
  );
}