'use client';

import { Menu, Gem } from 'lucide-react';
import Link from 'next/link';

import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetTrigger } from '@/components/ui/sheet';
import { useState } from 'react';

const navLinks = [
  { name: 'Produkty', href: '#produkty' },
  { name: 'Referencje', href: '#referencje' },
  { name: 'O nas', href: '#o-nas' },
];

export default function Header() {
  const [isMenuOpen, setMenuOpen] = useState(false);

  return (
    <header className="sticky top-0 z-50 w-full border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
      <div className="container flex h-16 items-center">
        <Link href="/" className="mr-6 flex items-center space-x-2">
          <Gem className="h-6 w-6 text-primary" />
          <span className="font-bold font-headline text-lg">EPIR Art Jewellery</span>
        </Link>
        <nav className="hidden md:flex flex-1 items-center space-x-6 text-sm font-medium">
          {navLinks.map((link) => (
            <Link key={link.name} href={link.href} className="text-foreground/70 transition-colors hover:text-foreground">
              {link.name}
            </Link>
          ))}
        </nav>
        <div className="flex flex-1 items-center justify-end space-x-4">
          <Button asChild className="hidden md:inline-flex bg-accent text-accent-foreground hover:bg-accent/90">
            <a href="https://www.epir-art.com/konsultacja" target="_blank" rel="noopener noreferrer">
              Zamów Konsultację
            </a>
          </Button>
          <Sheet open={isMenuOpen} onOpenChange={setMenuOpen}>
            <SheetTrigger asChild>
              <Button variant="ghost" className="md:hidden">
                <Menu className="h-6 w-6" />
                <span className="sr-only">Otwórz menu</span>
              </Button>
            </SheetTrigger>
            <SheetContent side="left">
              <Link href="/" className="mr-6 flex items-center space-x-2 mb-8" onClick={() => setMenuOpen(false)}>
                <Gem className="h-6 w-6 text-primary" />
                <span className="font-bold font-headline text-lg">EPIR Art Jewellery</span>
              </Link>
              <nav className="flex flex-col space-y-4">
                {navLinks.map((link) => (
                  <Link
                    key={link.name}
                    href={link.href}
                    onClick={() => setMenuOpen(false)}
                    className="text-lg font-medium text-foreground/70 transition-colors hover:text-foreground"
                  >
                    {link.name}
                  </Link>
                ))}
                <Button asChild className="mt-4 bg-accent text-accent-foreground hover:bg-accent/90">
                  <a href="https://www.epir-art.com/konsultacja" target="_blank" rel="noopener noreferrer">
                    Zamów Konsultację
                  </a>
                </Button>
              </nav>
            </SheetContent>
          </Sheet>
        </div>
      </div>
    </header>
  );
}