import Image from 'next/image';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';

const products = [
  {
    name: 'Pierścionek "Aura"',
    price: '1 200 PLN',
    image: 'https://picsum.photos/400/400?random=1',
    hint: 'jewelry ring',
  },
  {
    name: 'Naszyjnik "Galaktyka"',
    price: '2 500 PLN',
    image: 'https://picsum.photos/400/400?random=2',
    hint: 'jewelry necklace',
  },
  {
    name: 'Kolczyki "Krople Rosy"',
    price: '950 PLN',
    image: 'https://picsum.photos/400/400?random=3',
    hint: 'jewelry earrings',
  },
  {
    name: 'Bransoletka "Nieskończoność"',
    price: '1 800 PLN',
    image: 'https://picsum.photos/400/400?random=4',
    hint: 'jewelry bracelet',
  },
];

export default function Products() {
  return (
    <section id="produkty" className="py-12 md:py-24 lg:py-32 bg-secondary">
      <div className="container px-4 md:px-6">
        <div className="flex flex-col items-center justify-center space-y-4 text-center">
          <div className="space-y-2">
            <h2 className="text-3xl font-headline font-bold tracking-tighter sm:text-5xl">Nasze Bestsellery</h2>
            <p className="max-w-[900px] text-muted-foreground md:text-xl/relaxed lg:text-base/relaxed xl:text-xl/relaxed">
              Każdy produkt to unikatowa opowieść, stworzona z najwyższej jakości materiałów i artystycznej precyzji.
            </p>
          </div>
        </div>
        <div className="mx-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 mt-12">
          {products.map((product) => (
            <Card key={product.name} className="overflow-hidden shadow-lg hover:shadow-2xl transition-shadow duration-300 group">
              <CardHeader className="p-0 overflow-hidden">
                <Image
                  src={product.image}
                  alt={product.name}
                  width={400}
                  height={400}
                  className="w-full h-auto object-cover aspect-square group-hover:scale-105 transition-transform duration-300"
                  data-ai-hint={product.hint}
                />
              </CardHeader>
              <CardContent className="p-6">
                <CardTitle className="text-xl font-headline mb-2">{product.name}</CardTitle>
                <Badge variant="secondary" className="text-lg font-bold text-primary bg-primary/10">
                  {product.price}
                </Badge>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}